\title{The Arithmetic Heart of Korselt's Criterion:\\
A Verified Bridge from the Universal Fermat Condition\\ to Local Divisibility}
\author{Aristotle (Harmonic)}
\date{2026-06-15}

\begin{document}
\maketitle

\begin{abstract}
We present a fully rigorous development of the central arithmetic implication
underlying Korselt's criterion for Carmichael numbers. The classical criterion
states that a composite integer $n$ is a Carmichael number if and only if $n$ is
squarefree and $(p-1)\mid(n-1)$ for every prime $p\mid n$. The deep direction is
the extraction of the \emph{local divisibility} conditions from the \emph{global}
behavior of $n$ under exponentiation. We isolate this extraction as a
self-contained theorem: if every unit of the residue ring $\Z/n\Z$ satisfies
$u^{\,n-1}=1$ --- the universal Fermat condition restricted to coprime bases ---
then for every prime divisor $p$ of $n$ one has $(p-1)\mid(n-1)$. The proof
proceeds in three movements: (i) transport of the universal Fermat condition
along the surjective unit-reduction homomorphism $\units{n}\twoheadrightarrow
\units{p}$; (ii) the elementary order-divides-exponent principle valid in any
monoid; and (iii) the cyclicity of $\units{p}$, which forces the order of a
primitive root to equal $p-1$. A noteworthy by-product is that the squarefreeness
hypothesis, customarily quoted as part of Korselt's criterion, is \emph{not}
required for this local-divisibility step. We give full statements of all
supporting lemmas, complete proof sketches, an algorithmic interpretation as a
Carmichael-number recognizer, and a discussion of the broader ``transport along a
surjection'' proof pattern.
\end{abstract}

\noindent\textbf{Keywords:} Carmichael numbers, Korselt's criterion, Fermat
pseudoprimes, cyclic groups, primitive roots, unit groups, order of an element,
primality testing.

\medskip
\noindent\textbf{MSC 2020:} 11A51, 11A07, 20K01.

\section{Introduction}

\subsection{Fermat's test and its impostors}
Fermat's Little Theorem asserts that for a prime $p$ and an integer $a$ with
$p\nmid a$,
\[
a^{\,p-1}\equiv 1 \pmod p.
\]
The contrapositive yields a one-sided primality test: if $a^{\,n-1}\not\equiv 1
\pmod n$ for some base $a$ coprime to $n$, then $n$ is composite. The test is
computationally cheap, but it admits \emph{absolute} counterexamples: composite
numbers $n$ for which $a^{\,n-1}\equiv 1 \pmod n$ for \emph{every} $a$ coprime to
$n$. These are the \textbf{Carmichael numbers}. The smallest is
$561 = 3\cdot 11\cdot 17$; the sequence continues
$1105, 1729, 2465, 2821, 6601,\dots$, and Alford, Granville, and Pomerance proved
in 1994 that there are infinitely many.

\subsection{Korselt's criterion}
The structural classification is due to A. Korselt (1899).

\begin{theorem}[Korselt's criterion]
A composite integer $n>1$ is a Carmichael number if and only if $n$ is squarefree
and for every prime $p\mid n$ we have $(p-1)\mid(n-1)$.
\end{theorem}

The criterion replaces an infinite verification (over all coprime bases) by a
finite one (over the prime factors of $n$). The \emph{converse} (Korselt
conditions $\Rightarrow$ Carmichael) is a Chinese-Remainder-Theorem assembly. The
\emph{forward} direction (Carmichael $\Rightarrow$ Korselt conditions) is where
the structural insight lives: it must manufacture the clean divisibility relation
$(p-1)\mid(n-1)$ from the mere fact that $n$ fools Fermat's test universally.

\subsection{Contribution}
We formalize and prove, from first principles, the \textbf{arithmetic core} of
the forward direction (Theorem~\ref{thm:main}). We observe (Section~\ref{sec:sqf})
that \textbf{squarefreeness is not used} in the proof, a small but genuine
sharpening of the usual presentation.

\section{Preliminaries and notation}
Throughout, $n$ and $p$ are positive integers with $p$ prime and $p\mid n$. We
write $\Z/n\Z$ for the ring of integers modulo $n$; $\units{n}$ for its group of
units (residues coprime to $n$, of order $\varphi(n)$); $\ord(g)$ for the order
of an element $g$ of a monoid (the least $k>0$ with $g^k=1$). We use two classical
facts:
\begin{itemize}
  \item \textbf{(Reduction homomorphism.)} For $p\mid n$ there is a ring map
  $\Z/n\Z\to\Z/p\Z$ inducing a group homomorphism on units, the
  \emph{unit-reduction map} $\reduce:\units{n}\to\units{p}$.
  \item \textbf{(Gauss's primitive root theorem.)} For a prime $p$, the group
  $\units{p}$ is cyclic of order $p-1$.
\end{itemize}

\section{Supporting lemmas}

\begin{lemma}[Order divides a universal exponent]\label{lem:ord}
Let $M$ be a monoid and $m\in\N$. If $g^m=1$ for every $g\in M$, then for every
$g\in M$, $\ord(g)\mid m$.
\end{lemma}
\begin{proof}[Proof sketch]
Fix $g$; by hypothesis $g^m=1$. The order of an element divides an exponent $m$
precisely when that exponent annihilates the element, i.e. $g^m=1$. Apply this. 
\end{proof}

\begin{lemma}[Orders divide along homomorphisms]\label{lem:hom}
Let $\varphi\colon G\to H$ be a group homomorphism. Then for every $g\in G$,
$\ord(\varphi(g))\mid \ord(g)$.
\end{lemma}
\begin{proof}[Proof sketch]
Let $k=\ord(g)$, so $g^k=1$. Then $\varphi(g)^k=\varphi(g^k)=\varphi(1)=1$, using
that $\varphi$ preserves powers and the identity; hence $\ord(\varphi(g))\mid k$.
\end{proof}

\begin{lemma}[Surjectivity of unit reduction]\label{lem:surj}
Let $n\ge 1$ and $p\mid n$. The unit-reduction homomorphism
$\reduce\colon\units{n}\to\units{p}$ is surjective.
\end{lemma}
\begin{proof}[Proof sketch]
This is the multiplicative content of the Chinese Remainder Theorem. Write
$n=p^a m$ with $\gcd(p,m)=1$. Given $v$ coprime to $p$, lift it to a unit mod
$p^a$ (the reduction $\units{p^a}\twoheadrightarrow\units{p}$ is surjective) and
choose $u\equiv v\pmod{p^a}$, $u\equiv 1\pmod m$ by CRT; then $u\in\units{n}$ and
$\reduce(u)=v$. 
\end{proof}

\section{The main theorem}

\begin{theorem}[Local divisibility from the universal Fermat condition]\label{thm:main}
Let $n\ge 1$ and let $p$ be prime with $p\mid n$. Suppose
\[
(\star)\qquad \forall\, u\in\units{n},\quad u^{\,n-1}=1.
\]
Then $(p-1)\mid(n-1)$.
\end{theorem}

\begin{proof}
\textbf{Movement 1 --- Transport $(\star)$ to $\units{p}$.}
We claim every $v\in\units{p}$ satisfies $v^{\,n-1}=1$. By
Lemma~\ref{lem:surj}, $\reduce$ is surjective, so choose $u\in\units{n}$ with
$\reduce(u)=v$. Since $\reduce$ is a homomorphism,
\[
v^{\,n-1}=\reduce(u)^{\,n-1}=\reduce\!\left(u^{\,n-1}\right)=\reduce(1)=1,
\]
the third equality by $(\star)$. This gives the local condition
$(\star_p)\colon \forall\, v\in\units{p},\ v^{\,n-1}=1$.

\smallskip
\textbf{Movement 2 --- Extract an order divisibility.}
Apply Lemma~\ref{lem:ord} to $M=\units{p}$ with $m=n-1$; condition $(\star_p)$ is
exactly its hypothesis, so $\ord(g)\mid(n-1)$ for every $g\in\units{p}$.

\smallskip
\textbf{Movement 3 --- Invoke cyclicity.}
By Gauss's theorem $\units{p}$ is cyclic of order $p-1$, so there exists a
generator $g$ with $\ord(g)=\lvert\units{p}\rvert=p-1$. For this $g$, Movement~2
gives $\ord(g)\mid(n-1)$; substituting $\ord(g)=p-1$ yields $(p-1)\mid(n-1)$.
\end{proof}

\begin{remark}
The conclusion is $(p-1)\mid(n-1)$, \emph{not} merely $\exp(\units{p})\mid(n-1)$.
The upgrade is supplied entirely by cyclicity: in a cyclic group the exponent
equals the order. Without a primitive root, Movement~3 collapses and one obtains
only the weaker statement about the group exponent.
\end{remark}

\section{Algorithmic interpretation}
Theorem~\ref{thm:main} is the soundness lemma behind a finite Carmichael
recognizer:
\begin{verbatim}
function isCarmichael(n):
    if n < 3 or isPrime(n):            return false
    factor n = p1^a1 * ... * pk^ak
    if any ai > 1:                      return false   # not squarefree
    for each prime pi:
        if (n - 1) mod (pi - 1) != 0:   return false   # Korselt local condition
    return true
\end{verbatim}
Theorem~\ref{thm:main} guarantees the local-condition loop is \emph{necessary}:
any Carmichael number must clear every $(p_i-1)\mid(n-1)$ check, so the test is
complete against Carmichael numbers. Equivalently, $(\star)$ says
$\lambda(n)\mid(n-1)$ for the Carmichael function $\lambda$ (the exponent of
$\units{n}$), and Theorem~\ref{thm:main} is the transfer
$\lambda(n)\mid(n-1)\Rightarrow(p-1)\mid(n-1)$.

\section{On the redundancy of squarefreeness}\label{sec:sqf}
\begin{proposition}[Inertness of squarefreeness]
The conclusion $(p-1)\mid(n-1)$ of Theorem~\ref{thm:main} holds under hypotheses
$p\mid n$ and $(\star)$ alone; adding ``$n$ squarefree'' neither strengthens nor
is used by the proof.
\end{proposition}
\begin{proof}[Justification]
The proof of Theorem~\ref{thm:main} invokes only $p\mid n$ (for $\reduce$ and its
surjectivity), $(\star)$, and the cyclicity/order of $\units{p}$ (depending only
on $p$ prime). None mention the multiplicity of $p$ in $n$.
\end{proof}
This is consistent with Korselt's criterion: squarefreeness is required for the
\emph{converse} assembly, since $\units{p^a}$ with $a\ge 2$ is not annihilated by
$p-1$.

\section{Worked example: $n=561$}
Let $n=561=3\cdot 11\cdot 17$, so $n-1=560$. For $p=17$: $\reduce$ is surjective;
under $(\star)$ every $v\in\units{17}$ satisfies $v^{560}=1$; hence every order
divides $560$; $\units{17}$ is cyclic of order $16$ with primitive root $3$
($\ord_{17}(3)=16$), so $16\mid 560$ (indeed $560=16\cdot 35$). Likewise
$2\mid 560$ and $10\mid 560$. By contrast $15=3\cdot5$ fails: $4\nmid 14$, so $15$
is not Carmichael ($2^{14}\equiv 4\pmod{15}$).

\section{The proof pattern in a wider landscape}
Theorem~\ref{thm:main} exemplifies a recurring template: (1) \emph{transport} a
universal hypothesis along a surjection to a better-understood object;
(2) \emph{extract} an annihilation/divisibility statement via a structural
invariant; (3) \emph{sharpen} using special structure of the target. The same
template appears in algebraic topology --- a four-term exact sequence
$A\to B\to C\to D$ with vanishing ends forces the middle map to be an isomorphism
(e.g. $\pi_3(S^2)\cong\Z$ via the Hopf fibration) --- and in information geometry,
where local Fisher data is transported and sharpened into global curvature.

\section{Discussion and future work}
A complete formal Korselt's criterion additionally requires the converse CRT
assembly, squarefreeness necessity in the converse, and the equivalence between
``Carmichael'' and the universal unit condition $(\star)$. Recasting $(\star)$ as
$\lambda(n)\mid(n-1)$ connects to Lehmer's totient problem; building on the
recognizer one can target the Alford--Granville--Pomerance infinitude theorem.

\section{Conclusion}
We isolated and rigorously proved the arithmetic heart of Korselt's criterion:
the universal Fermat condition on the units of $\Z/n\Z$ forces, for each prime
$p\mid n$, the divisibility $(p-1)\mid(n-1)$. The proof is a clean three-movement
argument --- transport along surjective unit reduction, order-divides-exponent,
and cyclicity of $\units{p}$ --- and reveals that the customary squarefreeness
hypothesis is inert for this step.

\appendix
\section{Statements as formalized}
\begin{itemize}
  \item \textbf{Lemma~\ref{lem:ord}.}
  $\forall\,(M:\text{Monoid})(m:\N),\ (\forall g, g^m=1)\to\forall g,\ \ord(g)\mid m$.
  \item \textbf{Lemma~\ref{lem:hom}.}
  $\forall\,(\varphi:G\to_* H)(g),\ \ord(\varphi(g))\mid\ord(g)$.
  \item \textbf{Lemma~\ref{lem:surj}.}
  $\forall\{n,p\}[\mathrm{NeZero}\,n](h:p\mid n),\
  \mathrm{Surjective}(\mathrm{unitReduce}\,h)$.
  \item \textbf{Theorem~\ref{thm:main}.}
  $\forall\{n\}[\mathrm{NeZero}\,n](p)[\mathrm{Fact}\,p.\mathrm{Prime}],\
  p\mid n\to \mathrm{Squarefree}\,n\to(\forall u:\units{n},\,u^{\,n-1}=1)\to
  (p-1)\mid(n-1)$, with \texttt{Squarefree} retained for interface compatibility
  but unused.
\end{itemize}

